mapper.insert:
INSERT INTO fulfillment_shadow_quarantine (table_name,row_key,source_sequence,reason,payload)
VALUES (#{row.tableName},#{row.rowKey},#{sequence},#{reason},#{row.payload})
ON DUPLICATE KEY UPDATE source_sequence=#{sequence},reason=#{reason},payload=#{row.payload}

choose.when:
INSERT INTO fulfillment_order_locks (
  order_id
) VALUES (
  #{values.order_id}
)
ON DUPLICATE KEY UPDATE
  order_id=#{values.order_id}

INSERT INTO fulfillment_command_ids (
  command_id,
  order_id
) VALUES (
  #{values.command_id},
  #{values.order_id}
)
ON DUPLICATE KEY UPDATE
  order_id=#{values.order_id}
